function renderPostpartum(){var body=card('Imediatamente após o parto','🫶','<p>Após a dequitação há queda importante da resistência insulínica. Na <b>DMG</b>, a farmacoterapia utilizada exclusivamente durante a gestação geralmente pode ser suspensa, com reavaliação glicêmica. Não aplicar automaticamente esse fluxo a DM1, DM2 ou diabetes manifesto diagnosticado na gestação.</p>')+
 card('TOTG 75 g pós-parto','🧪','<p>Programar reclassificação metabólica entre <b>4 e 12 semanas após o parto</b>. Os pontos de corte da gestação (92/180/153) <b>não são utilizados</b> no pós-parto.</p><label class="gm-master-label">Data do parto<input id="gm-birth-date" type="date"></label><button class="gm-master-primary" id="gm-post-window">Calcular janela</button><div id="gm-post-window-out"></div>')+
 card('Interpretar TOTG pós-parto','📊','<div class="gm-master-input-row"><label>Jejum (mg/dL)<input id="gm-post-fasting" type="number"></label><label>2 h após 75 g (mg/dL)<input id="gm-post-2h" type="number"></label></div><div class="gm-post-criteria"><span><b>Normal</b> jejum &lt;100 e 2 h &lt;140</span><span><b>Pré-diabetes</b> jejum 100–125 ou 2 h 140–199</span><span><b>Diabetes</b> jejum ≥126 ou 2 h ≥200</span></div><button class="gm-master-primary" id="gm-post-interpret">Interpretar</button><div id="gm-post-result"></div>')+
 card('Seguimento','🌿','<p>Antecedente de DMG aumenta o risco futuro de DM2. Orientar peso saudável, alimentação, atividade física, rastreamento metabólico periódico, planejamento reprodutivo e rastreamento precoce em futuras gestações.</p>')+
 card('Aleitamento','🤱','<p>Incentivar aleitamento materno e integrar o puerpério às estratégias de prevenção metabólica e acompanhamento da mulher.</p>');
 return shell('9. Pós-parto','Reclassificação metabólica e prevenção de longo prazo',body,'SBD e protocolos nacionais/federais contemporâneos: TOTG 75 g entre 4–12 semanas e critérios não gestacionais para interpretação.');}
function bindPostpartum(){var w=document.getElementById('gm-post-window');if(w)w.onclick=function(){var v=document.getElementById('gm-birth-date').value,out=document.getElementById('gm-post-window-out'),a=addWeeks(v,4),b=addWeeks(v,12);if(!a){out.innerHTML=alertBox('Informe a data do parto','A data é necessária para calcular a janela.','warn');return;}out.innerHTML=alertBox('Janela para TOTG','De <b>'+dateBR(a)+'</b> até <b>'+dateBR(b)+'</b> (4–12 semanas pós-parto).','info');};var i=document.getElementById('gm-post-interpret');if(i)i.onclick=function(){var f=n(document.getElementById('gm-post-fasting').value),h=n(document.getElementById('gm-post-2h').value),out=document.getElementById('gm-post-result');if(f==null||h==null){out.innerHTML=alertBox('Preencha os dois valores','Informe jejum e glicemia de 2 horas.','warn');return;}if(f>=126||h>=200)out.innerHTML=alertBox('Resultado compatível com diabetes','Jejum ≥126 mg/dL ou 2 h ≥200 mg/dL. Confirmar/avaliar conforme critérios diagnósticos da população não gestante e contexto clínico.','danger');else if(f>=100||h>=140)out.innerHTML=alertBox('Resultado compatível com pré-diabetes','Jejum 100–125 mg/dL ou 2 h 140–199 mg/dL. Orientar prevenção e seguimento metabólico.','warn');else out.innerHTML=alertBox('Normoglicemia','Jejum <100 mg/dL e 2 h <140 mg/dL. Manter rastreamento periódico devido ao antecedente de DMG.','ok');};}
