function patchMenu(){var m=menu();if(!m)return false;if(m.getAttribute('data-master-v230')==='1')return true;m.setAttribute('data-master-v230','1');m.innerHTML=menuMarkup();m.addEventListener('click',function(e){var b=e.target.closest('[data-master-topic]');if(b)openTopic(b.dataset.masterTopic);});return true;}
function patchTop(){var r=root();if(!r)return;var back=r.querySelector('.gm-dmg-new-back');if(back&&!back.getAttribute('data-master-top')){var c=back.cloneNode(true);c.setAttribute('data-master-top','1');back.parentNode.replaceChild(c,back);c.onclick=function(e){e.preventDefault();var d=detail();if(d&&d.hidden===false)showMenu();else closeModule();};}}
function init(){addStyle();if(!patchMenu()){setTimeout(init,120);return;}patchTop();}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();window.addEventListener('load',init,{once:true});
window.GestaMedDMGMaster={open:openTopic,menu:showMenu,state:state};
